// iter 137 — regression guards for the 6 CodeQL code-scanning alerts
// closed on 2026-06-14. Each test pins the fixed behaviour so the alert
// cannot silently reopen.
import { describe, it, expect } from 'vitest';
import { basename } from 'node:path';
import { templateDir } from '../src/index.js';

describe('CodeQL #2 — incomplete string escaping (templateDir)', () => {
  it('replaces EVERY colon, not just the first', () => {
    // A hypothetical multi-colon id must not leave a stray ':' in the final
    // path segment. (Check the basename, not the whole path — on Windows the
    // absolute prefix legitimately contains a drive-letter colon, e.g. C:\.)
    const seg = basename(templateDir('vertical:sub:thing'));
    expect(seg).not.toContain(':');
    expect(seg).toBe('vertical_sub_thing');
  });

  it('still maps the normal single-colon id', () => {
    expect(templateDir('vertical:devops')).toContain('vertical_devops');
  });
});

describe('CodeQL #1/#3 — polynomial regex in kebab (ReDoS)', () => {
  // kebab is not exported; exercise it through recommendPlan's name field
  // would require a full profile. Instead assert the property that the fix
  // guarantees: linear time on a pathological all-separator input.
  it('handles a pathological all-separator string in linear time', async () => {
    // Re-import the analyze-repo module and reach the kebab behaviour via
    // recommendPlan, which calls kebab(`${name}-harness`).
    const { recommendPlan } = await import('../src/analyze-repo.js');
    const evil = '-'.repeat(100000);
    const profile = {
      name: evil,
      languages: [],
      hasMcp: false,
      hasClaude: false,
      hasCodex: false,
      hasCi: false,
      buildCommands: [],
      testCommands: [],
      tokens: [],
    } as Parameters<typeof recommendPlan>[0];
    const start = Date.now();
    const plan = recommendPlan(profile);
    const elapsed = Date.now() - start;
    // Fix guarantees linear time: 100k separators must collapse near-instantly.
    // A super-linear regex would blow well past this on 100k chars.
    expect(elapsed).toBeLessThan(1000);
    // And the name must be a clean kebab with no leading/trailing/double dashes.
    expect(plan.name).not.toMatch(/^-|-$|--/);
  });

  it('produces clean kebab output for ordinary names', async () => {
    const { recommendPlan } = await import('../src/analyze-repo.js');
    const profile = {
      name: '  My Cool Repo!!  ',
      languages: [],
      hasMcp: false,
      hasClaude: false,
      hasCodex: false,
      hasCi: false,
      buildCommands: [],
      testCommands: [],
      tokens: [],
    } as Parameters<typeof recommendPlan>[0];
    const plan = recommendPlan(profile);
    expect(plan.name).toBe('my-cool-repo-harness');
  });
});

describe('CodeQL #4 — second-order command injection (from-repo URL allowlist)', () => {
  // The validation lives inline in main()'s from-repo branch. We assert the
  // allowlist regex directly mirrors the source so the guard is documented
  // + locked. (The exact regex is duplicated here intentionally — if the
  // source regex changes, this test should be updated in lockstep, forcing
  // a reviewer to re-confirm the security property.)
  const ALLOWED = /^(https?:\/\/|git:\/\/|ssh:\/\/|git@)/;

  it('accepts legitimate repo URLs', () => {
    expect(ALLOWED.test('https://github.com/ruvnet/agent-harness-generator')).toBe(true);
    expect(ALLOWED.test('http://example.com/repo.git')).toBe(true);
    expect(ALLOWED.test('git://example.com/repo.git')).toBe(true);
    expect(ALLOWED.test('ssh://git@github.com/ruvnet/x.git')).toBe(true);
    expect(ALLOWED.test('git@github.com:ruvnet/x.git')).toBe(true);
  });

  it('rejects option-injection payloads that start with a dash', () => {
    expect(ALLOWED.test('--upload-pack=touch /tmp/pwned')).toBe(false);
    expect(ALLOWED.test('-c core.fsmonitor=evil')).toBe(false);
    expect(ALLOWED.test('--config=x')).toBe(false);
  });

  it('rejects non-URL local paths and file:// that could escape', () => {
    expect(ALLOWED.test('/etc/passwd')).toBe(false);
    expect(ALLOWED.test('file:///etc/passwd')).toBe(false);
    expect(ALLOWED.test('../../some/path')).toBe(false);
  });
});

import { describe, it, expect } from 'vitest';
import {
  COMPLETION_SCOPES,
  InMemoryKeyStore,
  extractApiKey,
  hashKey,
  highestHeldTier,
  holdsTier,
  isValidKeyFormat,
  keyPrefix,
  verifyApiKey,
} from '../src/auth/apiKey';

// Valid cog_ keys = cog_ + 64 hex chars (ADR-203 §6).
const VALID = 'cog_' + 'a'.repeat(64);
const VALID2 = 'cog_' + 'b'.repeat(64);

function store(): InMemoryKeyStore {
  const s = new InMemoryKeyStore();
  s.add(VALID, {
    permissions: [COMPLETION_SCOPES.low, COMPLETION_SCOPES.high],
    rateLimit: 120,
    active: true,
    expiresAt: null,
    accountId: 'acct_1',
  });
  return s;
}

describe('auth — cog_ key scheme (ADR-203 §6)', () => {
  it('validates the cog_ + 64-hex format', () => {
    expect(isValidKeyFormat(VALID)).toBe(true);
    expect(isValidKeyFormat('cog_short')).toBe(false);
    expect(isValidKeyFormat('sk-openai-style')).toBe(false);
    expect(isValidKeyFormat('cog_' + 'z'.repeat(64))).toBe(false); // z not hex
  });

  it('SHA-256 hashes the key and exposes only a 12-char prefix', () => {
    expect(hashKey(VALID)).toHaveLength(64);
    expect(hashKey(VALID)).not.toContain(VALID); // never the plaintext
    expect(keyPrefix(VALID)).toBe('cog_aaaaaaaa');
    expect(keyPrefix(VALID)).toHaveLength(12);
  });

  it('extracts the key from X-API-Key (preferred) or Bearer', () => {
    expect(extractApiKey({ 'x-api-key': VALID })).toBe(VALID);
    expect(extractApiKey({ authorization: `Bearer ${VALID}` })).toBe(VALID);
    expect(extractApiKey({ authorization: `bearer ${VALID}` })).toBe(VALID); // case-insensitive
    // X-API-Key wins when both present
    expect(extractApiKey({ 'x-api-key': VALID, authorization: `Bearer ${VALID2}` })).toBe(VALID);
    expect(extractApiKey({})).toBeUndefined();
  });

  it('rejects missing / malformed / unknown keys with 401', async () => {
    const s = store();
    expect((await verifyApiKey(undefined, s))).toMatchObject({ ok: false, status: 401, code: 'missing_api_key' });
    expect((await verifyApiKey('nope', s))).toMatchObject({ ok: false, status: 401, code: 'invalid_api_key' });
    expect((await verifyApiKey(VALID2, s))).toMatchObject({ ok: false, status: 401, code: 'invalid_api_key' });
  });

  it('rejects inactive and expired keys with an OPAQUE 401 (granular reason in logs only)', async () => {
    const s = new InMemoryKeyStore();
    s.add(VALID, { permissions: [COMPLETION_SCOPES.low], rateLimit: 1, active: false, expiresAt: null });
    s.add(VALID2, { permissions: [COMPLETION_SCOPES.low], rateLimit: 1, active: true, expiresAt: new Date(Date.now() - 1000) });
    // External wire code/error must NOT reveal key state (anti-enumeration, §6) — collapsed to
    // the same invalid_api_key / 'Invalid API key.' as an unknown key; reason kept in logCode.
    expect((await verifyApiKey(VALID, s))).toMatchObject({ ok: false, code: 'invalid_api_key', error: 'Invalid API key.', logCode: 'key_inactive' });
    expect((await verifyApiKey(VALID2, s))).toMatchObject({ ok: false, code: 'invalid_api_key', error: 'Invalid API key.', logCode: 'key_expired' });
  });

  it('returns an indistinguishable response for unknown vs inactive vs expired keys', async () => {
    const s = new InMemoryKeyStore();
    s.add(VALID, { permissions: [COMPLETION_SCOPES.low], rateLimit: 1, active: false, expiresAt: null });
    const unknown = await verifyApiKey(VALID2, s); // valid format, not in store
    const inactive = await verifyApiKey(VALID, s);
    if (unknown.ok || inactive.ok) throw new Error('expected both to fail');
    expect(unknown.status).toBe(inactive.status);
    expect(unknown.code).toBe(inactive.code);
    expect(unknown.error).toBe(inactive.error);
  });

  it('accepts a valid, active, scoped key', async () => {
    const out = await verifyApiKey(VALID, store());
    expect(out.ok).toBe(true);
    if (out.ok) {
      expect(out.key.accountId).toBe('acct_1');
      expect(out.rawPrefix).toBe('cog_aaaaaaaa');
    }
  });

  it('computes held scopes (caps auto escalation, §6 item 2)', async () => {
    const out = await verifyApiKey(VALID, store());
    if (!out.ok) throw new Error('expected ok');
    expect(highestHeldTier(out.key)).toBe('high');
    expect(holdsTier(out.key, 'low')).toBe(true);
    expect(holdsTier(out.key, 'mid')).toBe(false); // low+high only
    expect(holdsTier(out.key, 'high')).toBe(true);
  });
});

