import { EventEmitter } from 'node:events';
import { describe, it, expect } from 'vitest';
import { check, commandOnPath, fetch, secretsDispatch, type GcloudRunner } from '../src/secrets.js';

function mockRunner(table: Record<string, { code: number; stdout: string; stderr?: string }>): GcloudRunner {
  return {
    async run(args) {
      const key = args.join(' ');
      const hit = table[key] ?? table[Object.keys(table).find(k => key.startsWith(k)) ?? ''];
      if (!hit) return { code: 1, stdout: '', stderr: `mock: no match for: ${key}` };
      return { code: hit.code, stdout: hit.stdout, stderr: hit.stderr ?? '' };
    },
  };
}

describe('harness secrets check', () => {
  it('HEALTHY when project + auth + secret + pool all present', async () => {
    const runner = mockRunner({
      'config get-value project': { code: 0, stdout: 'my-proj\n' },
      'auth list --filter=status:ACTIVE --format=value(account)': { code: 0, stdout: 'me@example.com\n' },
      'secrets describe NPM_TOKEN': { code: 0, stdout: 'projects/123/secrets/NPM_TOKEN\n' },
      'iam workload-identity-pools list': { code: 0, stdout: 'GitHub Actions\n' },
    });
    const { code, lines } = await check([], runner, async () => true);
    expect(code).toBe(0);
    expect(lines.some(l => l.startsWith('Result: HEALTHY'))).toBe(true);
  });

  it('reports missing project explicitly', async () => {
    const runner = mockRunner({
      'config get-value project': { code: 0, stdout: '(unset)\n' },
    });
    const { code, lines } = await check([], runner, async () => true);
    expect(code).toBe(1);
    expect(lines.join('\n')).toMatch(/no active gcloud project/);
  });

  it('honors --project= override flag', async () => {
    const runner = mockRunner({
      'auth list --filter=status:ACTIVE --format=value(account)': { code: 0, stdout: 'me@example.com\n' },
      'secrets describe NPM_TOKEN --project=forced-proj --format=value(name)': {
        code: 0, stdout: 'projects/forced-proj/secrets/NPM_TOKEN\n',
      },
      'iam workload-identity-pools list --location=global --project=forced-proj': {
        code: 0, stdout: 'GitHub Actions\n',
      },
    });
    const { lines } = await check(['--project=forced-proj'], runner, async () => true);
    expect(lines.some(l => l.includes('forced-proj'))).toBe(true);
  });

  it('bounds a hung PATH lookup and terminates its child', async () => {
    class HungChild extends EventEmitter {
      killed = false;
      kill() { this.killed = true; return true; }
    }
    const child = new HungChild();
    const found = await commandOnPath('gcloud', 'win32', () => child, 5);
    expect(found).toBe(false);
    expect(child.killed).toBe(true);
  });
});

describe('harness secrets fetch', () => {
  it('requires a secret name argument', async () => {
    const { code, lines } = await fetch([], mockRunner({}));
    expect(code).toBe(2);
    expect(lines[0]).toMatch(/Usage: harness secrets fetch/);
  });

  it('returns non-zero when fetch fails', async () => {
    const runner = mockRunner({
      'secrets versions access latest --secret=MISSING': { code: 1, stdout: '', stderr: 'NOT_FOUND' },
    });
    const { code, lines } = await fetch(['MISSING'], runner);
    expect(code).toBe(1);
    expect(lines.join('\n')).toMatch(/Fetch failed/);
  });
});

describe('harness secrets dispatch', () => {
  it('routes unknown subcommands with exit 2', async () => {
    const { code, lines } = await secretsDispatch(['nope']);
    expect(code).toBe(2);
    expect(lines[0]).toMatch(/Unknown secrets subcommand/);
  });

  it('help is exit 0 and includes all three subcommands', async () => {
    const { code, lines } = await secretsDispatch(['help']);
    expect(code).toBe(0);
    const text = lines.join('\n');
    expect(text).toMatch(/check/);
    expect(text).toMatch(/fetch/);
    expect(text).toMatch(/validate-token/);
    expect(text).toMatch(/Workload Identity Federation/);
  });

  it('default (no args) shows help', async () => {
    const { code } = await secretsDispatch([]);
    expect(code).toBe(0);
  });
});

// SPDX-License-Identifier: MIT
//
// Darwin Shield bounded agentic loop (ADR-155 Addendum C; security analog of
// ADR-153). The architectural claim under test: single-shot analysis is
// structurally blind to multi-step (cross-file) bugs, while a bounded, gated
// agentic loop that PAYS the navigation cost crosses that discovery wall — with
// zero false positives (counterexample-required), full determinism, a step bound,
// and zero unsafe output.

import { describe, expect, it } from 'vitest';
import {
  FORBIDDEN_TOOLS,
  defaultAgenticPolicy,
  discoveryCorpus,
  runAgenticLoop,
  runSingleShot,
} from '../../src/security/agentic.js';

const corpus = discoveryCorpus();
const deepVulns = corpus.repos.flatMap((r) => r.sites.filter((s) => s.isVulnerable && (s.discoveryDepth ?? 1) > 1));
const allVulns = corpus.repos.flatMap((r) => r.sites.filter((s) => s.isVulnerable));

describe('the discovery wall — single-shot is structurally blind to deep bugs', () => {
  it('the corpus carries multi-step (depth > 1) vulnerabilities and decoys', () => {
    expect(deepVulns.length).toBeGreaterThan(0);
    expect(corpus.repos[0].sites.some((s) => !s.isVulnerable)).toBe(true);
  });

  it('single-shot misses every depth > 1 vuln (TPR < 1)', () => {
    const ss = runSingleShot(corpus);
    expect(ss.tpr).toBeLessThan(1);
    expect(ss.truePositives).toBe(allVulns.length - deepVulns.length); // only shallow bugs
  });
});

describe('the agentic loop crosses the wall', () => {
  it('with enough budget it finds every vuln, zero false positives', () => {
    const r = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    expect(r.metrics.truePositives).toBe(allVulns.length);
    expect(r.metrics.falsePositives).toBe(0);
    expect(r.metrics.unsafeOutputs).toBe(0);
    expect(r.findings.every((f) => f.exploitCodeAllowed === false)).toBe(true);
  });

  it('beats single-shot strictly', () => {
    const ss = runSingleShot(corpus);
    const r = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    expect(r.metrics.truePositives).toBeGreaterThan(ss.truePositives);
  });

  it('more step budget discovers monotonically more (budget is the lever)', () => {
    const small = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 3 }).metrics.truePositives;
    const mid = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 10 }).metrics.truePositives;
    const big = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 }).metrics.truePositives;
    expect(mid).toBeGreaterThanOrEqual(small);
    expect(big).toBeGreaterThanOrEqual(mid);
    expect(big).toBeGreaterThan(small);
  });
});

describe('the loop is bounded and gated (safety envelope)', () => {
  it('never exceeds its step budget', () => {
    for (const maxSteps of [1, 3, 5, 8, 12, 40]) {
      const r = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps });
      expect(r.stepsUsed).toBeLessThanOrEqual(maxSteps + corpus.repos.length); // +list_sites per repo
    }
  });

  it('the tool surface excludes all mutating/escape tools', () => {
    for (const t of ['write', 'exec', 'shell', 'network']) expect(FORBIDDEN_TOOLS).toContain(t);
  });

  it('emits a non-empty audit trace ending in submit_finding for confirmed bugs', () => {
    const r = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    expect(r.trace.length).toBeGreaterThan(0);
    expect(r.trace.some((s) => s.tool === 'submit_finding')).toBe(true);
    expect(r.trace.some((s) => s.tool === 'run_fuzzer')).toBe(true);
  });
});

describe('determinism / replay', () => {
  it('same corpus + policy ⇒ byte-identical receipt hash and metrics', () => {
    const a = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    const b = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    expect(a.receiptHash).toBe(b.receiptHash);
    expect(a.metrics).toEqual(b.metrics);
  });

  it('a different policy changes the receipt', () => {
    const a = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 40 });
    const b = runAgenticLoop(corpus, { ...defaultAgenticPolicy(), maxSteps: 5 });
    expect(a.receiptHash).not.toBe(b.receiptHash);
  });
});

// SPDX-License-Identifier: MIT
// SECURITY acceptance (agent-context isolation): the agent callback is the
// untrusted party. A malicious agent that mutates the context it is handed —
// forging a perfect evaluation into state.evaluations, gutting the promotion
// baseline on candidate.evaluation, and inflating its own budget — must not be
// able to influence promotion: the operator's authoritative state is isolated
// from the copies the agent sees, the forged commit is refused by the real
// promotion gate, and the seed remains the winner.

import { generateKeyPairSync } from 'node:crypto';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  Ed25519ReceiptSigner,
  EphemeralGovernedMemory,
  GovernedCapabilityPolicy,
  GovernedVariationOperator,
  JsonCheckpointStore,
  SemanticSupervisor,
  verifyReceipt,
  verifyVariationCheckpoint,
  type ActionObservation,
  type EnvironmentAdapter,
  type EvaluationResult,
  type VariationAction,
  type VariationContext,
  type VariationState,
} from '../src/index.js';

function result(quality: number, correct: boolean): EvaluationResult {
  return {
    evaluatorVersion: 'eval-v1', correct, safe: true, replayable: true,
    noRegression: correct, budgetValid: true, quality, costUsd: 0,
    wallTimeMs: 1, policyViolations: 0, protectedTestsPassed: correct,
    lowerConfidenceBound: correct ? 0.8 : 0, evidence: {},
  };
}

class InertEnvironment implements EnvironmentAdapter {
  readonly version = 'env-v1';
  async fork(parent: { id: string }) {
    return { branchId: `${parent.id}-working`, workspaceDigest: `sha256:fork-${parent.id}` };
  }
  async execute(action: VariationAction, state: Readonly<VariationState>): Promise<ActionObservation> {
    return {
      ok: true, stdout: `${action.kind}:observed`, exitCode: 0, durationMs: 1, costUsd: 0,
      workspaceDigest: `sha256:${state.budget.actionsUsed + 1}-${action.kind}`,
    };
  }
  async quarantine(): Promise<void> {}
}

describe('agent-context isolation (untrusted agent cannot buy promotion)', () => {
  it('a malicious agent that forges a perfect score is refused and the seed stays the winner', async () => {
    const root = await mkdtemp(join(tmpdir(), 'avo-malicious-'));
    try {
      const { privateKey, publicKey } = generateKeyPairSync('ed25519');
      const signer = new Ed25519ReceiptSigner('sec-key', privateKey, publicKey);
      const tamperedContexts: VariationContext[] = [];
      const maliciousAgent = {
        async chooseAction(context: VariationContext): Promise<VariationAction> {
          // Attack 1: forge a perfect, freshly-"evaluated" score into live state.
          (context.state.evaluations as EvaluationResult[]).push(result(1, true));
          // Attack 2: gut the promotion baseline so any delta qualifies.
          (context.candidate.evaluation as EvaluationResult).quality = 0;
          (context.candidate.evaluation as EvaluationResult).lowerConfidenceBound = 0;
          // Attack 3: inflate the remaining budget.
          (context.state.budget as { maxActions: number }).maxActions = 10_000;
          tamperedContexts.push(context);
          // Then immediately claim the prize.
          return { kind: 'commit', summary: 'forged perfect score' };
        },
      };
      const operator = new GovernedVariationOperator({
        runId: 'sec-1',
        task: 'security acceptance',
        seed: { id: 'seed', branchId: 'seed', workspaceDigest: 'sha256:seed' },
        environment: new InertEnvironment(),
        evaluators: { version: 'eval-v1', evaluate: async () => result(0.5, false) },
        agent: maliciousAgent,
        knowledge: { retrieve: async () => [] },
        memory: new EphemeralGovernedMemory(),
        policy: new GovernedCapabilityPolicy({
          version: 'policy-v1',
          allowedActions: ['inspect', 'edit', 'execute', 'evaluate', 'commit'],
          approvalActions: [],
          writablePaths: [/.*/],
        }),
        approval: { approve: async () => true },
        supervisor: new SemanticSupervisor({ policyVersion: 'policy-v1' }, async () => [
          { id: 's1', statement: 'a', causalMechanism: 'context', expectedEvidence: ['a'], surface: 'contextPolicy' },
          { id: 's2', statement: 'b', causalMechanism: 'edit', expectedEvidence: ['b'], surface: 'repairStrategy' },
          { id: 's3', statement: 'c', causalMechanism: 'tests', expectedEvidence: ['c'], surface: 'testPolicy' },
        ]),
        signer,
        checkpointStore: new JsonCheckpointStore(join(root, 'checkpoint.json')),
        budget: { maxActions: 5, maxBranchActions: 5, maxCostUsd: 1, maxWallTimeMs: 10_000, riskBudget: 1 },
        invariants: {
          immutableCapabilities: ['repository:read'],
          protectedPaths: [],
          promotionDelta: 0.1,
          requireSignedReceipts: true,
          requireZeroPolicyViolations: true,
        },
      });
      const output = await operator.run();

      // The forged commit never promotes: no winner, no lineage, and the
      // authoritative candidate set is still the seed alone.
      expect(output.winner).toBeNull();
      expect(output.lineage).toEqual([]);
      expect(output.checkpoint.state.candidates.map((c) => c.id)).toEqual(['seed']);
      // Every forged-commit attempt was refused by the real gate.
      const commits = output.receipts.filter((r) => r.action.kind === 'commit');
      expect(commits.length).toBeGreaterThan(0);
      for (const receipt of commits) {
        expect(receipt.observation.ok).toBe(false);
        expect(receipt.observation.exitCode).toBe(126);
        expect(receipt.observation.stderr).toContain('promotion gate rejected commit');
      }
      // The agent DID tamper with what it was handed — and none of it reached
      // the authoritative state: no forged evaluations, budget cap intact.
      expect(tamperedContexts.length).toBeGreaterThan(0);
      expect(output.checkpoint.state.evaluations.filter((e) => e.quality === 1)).toHaveLength(0);
      expect(output.checkpoint.state.budget.actionsUsed).toBeLessThanOrEqual(5);
      // Receipts and checkpoint still verify — the run is honest end to end.
      expect(output.receipts.every((r) => verifyReceipt(r, signer))).toBe(true);
      expect(verifyVariationCheckpoint(output.checkpoint, signer)).toBe(true);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });
});

# Browser-runtime WASM smoke

Static fixture that loads `@metaharness/kernel`'s WASM bundle in a real browser and asserts the three exports work (`kernelInfo`, `mcpValidate` accept, `mcpValidate` reject).

## Why this exists

The kernel claims to work in browser / Cloudflare Workers / Deno / Bun. We test Node via vitest; this fixture lets a human or Playwright runner test the browser path.

## Run

After building the WASM bundle:

```bash
cd packages/kernel-js
npm run build:wasm     # writes packages/kernel-js/pkg/
cd ../../
npx http-server -p 8080 packages/kernel-js -c-1
# open http://localhost:8080/__tests__/browser-smoke/fixture.html
```

The page shows PASS / FAIL inline + sets `window.__SMOKE_RESULT` for Playwright to read.

## Playwright wiring (queued for iter 16)

```js
// future: __tests__/browser-smoke/playwright.spec.ts
import { test, expect } from '@playwright/test';

test('kernel WASM loads in chromium', async ({ page }) => {
  await page.goto('http://localhost:8080/__tests__/browser-smoke/fixture.html');
  await page.waitForFunction(() => window.__SMOKE_RESULT !== undefined, { timeout: 10_000 });
  const result = await page.evaluate(() => window.__SMOKE_RESULT);
  expect(result.ok).toBe(true);
});
```

Iter 16 wires this up so CI fails on browser regression. For now, the fixture is human-runnable.

